/**
 * @param {Array} arr
 * @return {(string | number | boolean | null)[][]}
 */
var jsonToMatrix = function(arr) {
    // Helper: recursively flatten a value, collecting path -> leaf value
    const flatten = (value, path, out) => {
        if (value !== null && typeof value === "object") {
            // Objects and arrays: arrays are keyed by index
            for (const key of Object.keys(value)) {
                flatten(value[key], path === "" ? key : path + "." + key, out);
            }
        } else {
            // Leaf: number, string, boolean or null
            out[path] = value;
        }
    };

    // 1. Flatten each row, collect all unique columns (paths)
    const rows = [];
    const columns = new Set();
    for (const item of arr) {
        const flat = {};
        flatten(item, "", flat);
        rows.push(flat);
        for (const key of Object.keys(flat)) columns.add(key);
    }

    // Default sort compares strings lexicographically
    const sortedCols = [...columns].sort();

    // 2. Build matrix: first row is sortedCols, following are per-object rows
    const matrix = [sortedCols];
    for (const flat of rows) {
        matrix.push(sortedCols.map(col => (col in flat ? flat[col] : "")));
    }
    return matrix;
};
